import type { AudioSegment } from '../../cognitiveProfile/battery';
import { playNaturalArabicAudio, stopNaturalArabicAudio } from '../../utils/naturalSpeech';
import { audioKey } from '../../cognitiveProfile/audioCatalog';

const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/** Pre-recorded clips (public/audio/v1), generated by scripts/generate-audio.ts. */
const AUDIO_BASE = '/audio/v1/';
interface AudioManifest {
  version: 1;
  voice: string;
  clips: Record<string, { file: string }>;
}
let manifestPromise: Promise<AudioManifest | null> | null = null;
let currentClip: HTMLAudioElement | null = null;

function loadManifest(): Promise<AudioManifest | null> {
  if (!manifestPromise) {
    manifestPromise = fetch(`${AUDIO_BASE}manifest.json`, { cache: 'force-cache' })
      .then((res) => (res.ok ? (res.json() as Promise<AudioManifest>) : null))
      .catch(() => null);
  }
  return manifestPromise;
}

/** Start fetching the manifest early so the first instruction plays without delay. */
export function preloadAudioManifest(): void {
  void loadManifest();
}

/** Play the recorded clip for this exact text, if one exists. Resolves false when there is none. */
async function playRecordedClip(text: string): Promise<boolean> {
  const manifest = await loadManifest();
  const clip = manifest?.clips[audioKey(text)];
  if (!clip) return false;
  return new Promise<boolean>((resolve) => {
    const audio = new Audio(AUDIO_BASE + clip.file);
    currentClip = audio;
    let settled = false;
    const finish = (played: boolean) => {
      if (settled) return;
      settled = true;
      if (currentClip === audio) currentClip = null;
      resolve(played);
    };
    audio.onended = () => finish(true);
    audio.onpause = () => finish(true); // stopSpeech() pauses the clip
    audio.onerror = () => finish(false);
    audio.play().catch(() => finish(false));
  });
}

/**
 * Speak one utterance and resolve when it ends. Uses the pre-recorded clip when available;
 * otherwise falls back to live synthesis, with an estimated duration when the engine never
 * reports the end (some browsers, or no Arabic voice installed).
 */
export async function speak(text: string): Promise<void> {
  if (await playRecordedClip(text)) return;
  const estimateMs = Math.max(1200, Array.from(text).length * 110 + 500);
  await new Promise<void>((resolve) => {
    let settled = false;
    const done = () => {
      if (!settled) {
        settled = true;
        resolve();
      }
    };
    playNaturalArabicAudio(text, { onEnd: done, onError: done })
      .then(() => setTimeout(done, estimateMs))
      .catch(done);
  });
}

export interface PlaybackHandle {
  cancelled: boolean;
}

/** Speak segments in order, calling onHighlight with each segment's highlight target. */
export async function speakSegments(
  segments: AudioSegment[],
  handle: PlaybackHandle,
  onHighlight?: (target: string | null) => void
): Promise<void> {
  for (const segment of segments) {
    if (handle.cancelled) return;
    onHighlight?.(segment.highlight ?? null);
    await speak(segment.text);
    if (handle.cancelled) return;
    if (segment.pauseAfterMs) await wait(segment.pauseAfterMs);
  }
  onHighlight?.(null);
}

export function stopSpeech(): void {
  if (currentClip) {
    currentClip.pause();
    currentClip = null;
  }
  stopNaturalArabicAudio();
}

export { wait };
